import { Group, PlaneGeometry, Mesh, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Plane geometry (static CTA shape) ---
  const geometry = new PlaneGeometry(2.5, 0.6);
  const material = new MeshBasicNodeMaterial();
  // Fallback surface color from design palette while texture loads
  material.color.setHex(0x0b0b10);
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // --- Load the gradient/grain texture ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = 'srgb';
      tex.needsUpdate = true;
      material.map = tex;
      material.needsUpdate = true;
    }).catch(() => {
      // Texture load failed – fallback colour remains visible
    });
  }

  // --- Interaction handlers (none for this static element) ---
  group.userData.handlers = {};

  // --- Cleanup (dispose GPU resources) ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
  };

  return group;
}
